import{z as A,x as n,o as s,c as P,q as r,j as i,D as e,d as o,s as l,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Paxos 谱系","description":"","frontmatter":{"title":"Paxos 谱系","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/con-paxos-family.md","filePath":"cs/con-paxos-family.md","lastUpdated":1791063341000}'),d={name:"cs/con-paxos-family.md"};function p(x,a,m,f,F,u){const t=n("Mermaid");return s(),P("div",null,[a[2]||(a[2]=r('<h1 id="paxos-谱系" tabindex="-1">Paxos 谱系 <a class="header-anchor" href="#paxos-谱系" aria-label="Permalink to &quot;Paxos 谱系&quot;">​</a></h1><div class="epigraph"><p>「Paxos」在工程里从来不是一个算法，是一族算法：领导者强度、日志语义、提交规则、配置变更，四个旋钮各拧各的——谱系不清，是 Paxos 难用的第一来源。</p><footer>—— 据 Lamport, ACM TOCS 1998 与 Paxos Made Simple, 2001；Chandra, Griesemer and Redstone, PODC 2007 整理</footer></div><p><a href="/cs/con-multi-raft">上一课</a>把共识横向切成几千份；本课回身把另一半家谱理清。主干课已分别走过 <a href="/cs/paxos">Paxos</a>、<a href="/cs/multi-paxos">Multi-Paxos</a> 与 <a href="/cs/viewstamped-replication">VR</a>，Raft 也读到了实现层；缺的是它们之间的关系图：谁补了谁的活性洞、谁把谁特例化、每个旋钮拧到哪里。立起这张图，再读任何一篇新共识论文都只需先标四个旋钮。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程里说「我们用 Paxos」时，歧义至少三层。第一层，经典 Paxos 是单值协议，与「日志」之间隔着 Multi-Paxos——而 Multi-Paxos 没有一份公认的规格：Lamport 2001 的极简版与 Paxos Made Live 的工程版，在领导者租约、日志空洞、成员变更上口径并不相同。第二层，Paxos 论文没说清领导者崩溃后日志怎么恢复，实现者各自发明，正确性参差。第三层，配置变更在早期论文是空缺，后来的联合共识、Vertical Paxos、Raft 单步变更各补一洞。不立谱系，每接手一个「Paxos 实现」都要从头猜它的旋钮位。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是谱系学的读法而非教程式讲法：按时间把主线一篇一篇立起来，每篇只记录三件事——它拧动了哪个旋钮、补了谁的活性或工程洞、为此付了什么代价；四个旋钮的坐标系留到机制一节收拢。这样安排的好处是增量化：此后再读任何新共识论文，只需回答「它拧了哪个旋钮」，不必重讲共识推导。</p><h3 id="主线与分支" tabindex="-1">主线与分支 <a class="header-anchor" href="#主线与分支" aria-label="Permalink to &quot;主线与分支&quot;">​</a></h3><p>主线按时间读。1998 年《The Part-Time Parliament》用希腊议会寓言包装算法，难读而少人问津；2001 年作者用十几页重写成 Paxos Made Simple——prepare 争承诺、accept 写值，单值定音。2007 年 Paxos Made Live 补工程件：稳定领导者把 prepare 按任期摊销、只提交无空洞前缀、master 租约与快照。2006 年 Fast Paxos 拧「轮次」旋钮：无竞争时一轮通信直接学习，代价是快轮多数派更大（\\(3f+1\\) 个接受者中快轮取 \\(2f+1\\)），有竞争退回经典两轮。<span class="marginnote">给个数字实例：\\(f=2\\) 时系统共有 \\(3f+1=7\\) 个接受者，经典轮拿 4 票（过半）就能定值，快轮却要 \\(2f+1=5\\) 票。「快」的代价是票仓更大——少了竞争时确实少跑一轮，可一旦碰上竞争还得退回去，平均收益取决于冲突频率。</span>2009 年 Vertical Paxos 把「谁当主」与「重配置」解耦，主由外部强一致配置面驱动。2013 年 EPaxos 把领导者旋钮拧到零：命令按 key 亲和分组，无冲突时任意副本一轮提交，广域网下省半个 RTT，代价是恢复协议的复杂度。2014 年 Raft 从另一头进：把 Multi-Paxos 特例化成强领导者——日志无空洞、只有最新日志当选、当前任期才提交——用约束换可理解性。<a href="/cs/zab-zookeeper">Zab</a> 与 VR 是同族旁支，主干已读。</p><p><span class="marginnote">同一算法的两种命运：寓言版难读而少人问津，十几页的重写版成了被引最广的分布式论文之一。今天实现者口中的「Paxos」，多数指 Multi-Paxos 的某个私有变体，而不是 2001 年那份极简单值协议。</span></p>',10)),(s(),i(B,null,{default:e(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P98%5B%22Paxos%20%E5%AF%93%E8%A8%80%E7%89%88%201998%22%5D%20--%3E%20P01%5B%22Paxos%20Made%20Simple%EF%BC%9A%E5%8D%95%E5%80%BC%202001%22%5D%0A%20%20P01%20--%3E%20MP%5B%22Multi-Paxos%EF%BC%9A%E7%A8%B3%E5%AE%9A%E9%A2%86%E5%AF%BC%E8%80%85%202007%22%5D%0A%20%20MP%20--%3E%20FP%5B%22Fast%20Paxos%EF%BC%9A%E5%BF%AB%E8%BD%AE%E4%B8%80%E8%BD%AE%202006%22%5D%0A%20%20MP%20--%3E%20VP%5B%22Vertical%20Paxos%EF%BC%9A%E5%A4%96%E9%83%A8%E9%85%8D%E7%BD%AE%E9%9D%A2%202009%22%5D%0A%20%20MP%20--%3E%20EP%5B%22EPaxos%EF%BC%9A%E6%8C%89%20key%20%E5%88%86%E6%9D%83%202013%22%5D%0A%20%20MP%20--%3E%20RAFT%5B%22Raft%EF%BC%9A%E5%BC%BA%E9%A2%86%E5%AF%BC%E8%80%85%E7%89%B9%E4%BE%8B%202014%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"四个旋钮给谱系一个坐标系。领导者强度：从 Raft 的唯一领导者，到 Multi-Paxos 的稳定提议者，到 EPaxos 的按 key 分权。日志语义：无空洞连续（Raft）与槽位独立（Paxos）——前者让回退与对齐有确定方向，后者允许乱序补槽但恢复协议复杂。提交规则：「当前任期多数派才提交」与「任意轮次证书」——前者防住旧任期条目自提交的陷阱。配置变更：联合共识、单步变更、Vertical Paxos 的外部配置面，三种写法都要保相邻多数派相交。读任何实现，先问四个旋钮的位置再谈正确性——工程里大多数「Paxos 之争」其实是旋钮没对齐。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"把「四个旋钮」想象成调音台上的四根推子：每个共识算法只是各推子的一组位置组合，而不是四台不同的机器。所谓「设计一个新共识协议」，多数时候其实是把某根推子从 A 档推到 B 档，再补上这一档带来的新问题（比如 EPaxos 把领导者推子推到零，就得自己发明恢复协议）。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"初学者容易以为「日志允许空洞」是缺陷、无空洞才是优点，实际上这是权衡：槽位独立让慢槽位不阻塞后面的写入（吞吐好），但恢复时得逐槽确认哪些已提交；无空洞日志让恢复方向唯一（直接对齐领导者），代价是前面卡住、后面全部干等。")],-1)),(s(),i(B,null,{default:e(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E4%B8%AA%E9%99%8C%E7%94%9F%E5%85%B1%E8%AF%86%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20K1%5B%22%E6%97%8B%E9%92%AE%E4%B8%80%EF%BC%9A%E9%A2%86%E5%AF%BC%E8%80%85%E5%BC%BA%E5%BA%A6%E6%98%AF%E5%93%AA%E4%B8%80%E6%A1%A3%EF%BC%9F%22%5D%0A%20%20K1%20--%3E%20K2%5B%22%E6%97%8B%E9%92%AE%E4%BA%8C%EF%BC%9A%E6%97%A5%E5%BF%97%E5%85%81%E8%AE%B8%E7%A9%BA%E6%B4%9E%E5%90%97%EF%BC%9F%22%5D%0A%20%20K2%20--%3E%20K3%5B%22%E6%97%8B%E9%92%AE%E4%B8%89%EF%BC%9A%E6%8F%90%E4%BA%A4%E7%9C%8B%E5%BD%93%E5%89%8D%E4%BB%BB%E6%9C%9F%E8%BF%98%E6%98%AF%E4%BB%BB%E6%84%8F%E8%AF%81%E4%B9%A6%EF%BC%9F%22%5D%0A%20%20K3%20--%3E%20K4%5B%22%E6%97%8B%E9%92%AE%E5%9B%9B%EF%BC%9A%E9%85%8D%E7%BD%AE%E5%8F%98%E6%9B%B4%E7%94%A8%E5%93%AA%E7%A7%8D%E5%86%99%E6%B3%95%EF%BC%9F%22%5D%0A%20%20K4%20--%3E%20V%5B%22%E5%9B%9B%E4%B8%AA%E6%97%8B%E9%92%AE%E4%BD%8D%E6%A0%87%E5%AE%8C%EF%BC%8C%E5%86%8D%E8%B0%88%E6%AD%A3%E7%A1%AE%E6%80%A7%E4%B8%8E%E9%80%89%E5%9E%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多数派相交与 FLP 不重证（主干与 <a href="/cs/flp-impossibility">FLP 课</a>已做）；拜占庭一族的 PBFT 不进本谱系；Fast Paxos 的完整 quorum 代数与 EPaxos 的恢复正确性证明是各自论文的题，本课只定位旋钮。也别把谱系读成进化链：EPaxos 不是 Raft 的替代，Fast Paxos 也未被淘汰——旋钮组合各有适用面，选型按延迟分布与运维能力，不按新旧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Paxos 是一族算法；领导者强度、日志语义、提交规则、配置变更是四个旋钮。</li><li>主线：1998 寓言版、2001 单值极简、2007 工程化 Multi-Paxos，Fast、Vertical、Egalitarian 各拧一个旋钮，2014 Raft 特例化强领导者。</li><li>Multi-Paxos 没有公认规格；接手实现先标旋钮位，再谈正确性。</li><li>Raft 的三条额外约束换实现秩序；EPaxos 的零领导者换广域 RTT，各付各的复杂度。</li><li>出处：Lamport, TOCS 1998 与 Paxos Made Simple, 2001；Chandra, Griesemer and Redstone, PODC 2007；Lamport, Fast Paxos, Distributed Computing 2006；Moraru et al., SOSP 2013；Ongaro and Ousterhout, ATC 2014。</li></ul>',4))])}const h=A(d,[["render",p]]);export{c as __pageData,h as default};
